//! @generated by xtask split-potions.
use super::prelude::*;

/// TouchOfInsanity — choose one cost-bearing card in hand and make it
/// free (cost 0) for the rest of combat. C# TouchOfInsanity.OnUse:
/// `CardSelectCmd.FromHand(prefs(1), filter: CostsEnergyOrStars)` →
/// `.FirstOrDefault()?.SetToFreeThisCombat()` — a player choice (single
/// pick) over the cost-bearing hand cards. Bead `sts2-rs-1xmxp` (closing
/// `sts2-rs-gbaft`) replaces the prior uniform-random pick (the
/// `NOTE(sts2-rs-sr3ql)` legacy-rng caveat is now resolved).
///
/// v0.111.0 `CostsEnergyOrStars` is true if either local-only or fully
/// modified energy/star costs are positive. A global surcharge can therefore
/// make a locally free card eligible. No candidates is a no-op; a single
/// candidate resolves directly; multiple candidates request one selection.
pub(crate) fn drink_touch_of_insanity(
    state: &mut CombatState,
    _target: Option<u8>,
) -> EffectResult {
    let candidates: smallvec::SmallVec<[sts2_core::CardUid; 10]> = state
        .player
        .hand
        .iter()
        .copied()
        .filter(|uid| {
            let idx = uid.0.get() as usize - 1;
            let c = &state.cards[idx];
            // Source checks both local-only and fully modified costs. Global
            // free effects do not hide a local cost, while a global surcharge
            // can make a locally free card eligible.
            let local_energy = if sts2_core::hooks::card_cost_locally_zeroed(state, c) {
                0
            } else {
                (i32::from(c.cost)
                    - c.combat_var(sts2_core::cards::VarKey::EnergyDiscountUntilPlayed)
                    + c.combat_var(sts2_core::cards::VarKey::SneckoPriorDiscountThisTurn))
                .max(0)
            };
            (c.cost >= 0
                && (local_energy > 0 || sts2_core::hooks::effective_card_cost(state, *uid) > 0))
                || sts2_core::effective_star_cost(c) > 0
                || sts2_core::effective_star_cost_in_combat(state, c) > 0
        })
        .collect();
    match candidates.as_slice() {
        [] => {}
        [uid] => state.set_card_free_this_combat(*uid),
        _ => {
            let options: Vec<sts2_core::ChoiceOption> = candidates
                .iter()
                .map(|&uid| {
                    let idx = uid.0.get() as usize - 1;
                    sts2_core::ChoiceOption {
                        card_id: state.cards[idx].card_id,
                        upgraded: state.cards[idx].upgraded,
                        card_uid: Some(uid),
                        source_pile: Some(sts2_core::cards::PileKind::Hand),
                    }
                })
                .collect();
            state.request_card_choice(sts2_core::ChoiceKind::MakeFreeInHand, options, 1, 1, false);
        }
    }
    EffectResult::Resolved
}
